fn validate_pll_outputs_47c(mode: Pllvcosel, voltage: VoltageScale, outputs: &[Option<Hertz>]) {
    // PLL output ceilings: H543 DS15168 Rev1 tables 44/45 and H553
    // DS15167 Rev1 tables 45/46. Consumers must also obey their own
    // bus/peripheral limits; those must not be confused with this PLL table.
    let maximum = match (mode, voltage) {
        (Pllvcosel::WideVco, VoltageScale::Scale0) => 250_000_000,
        (Pllvcosel::WideVco, VoltageScale::Scale1) => 200_000_000,
        (Pllvcosel::WideVco, VoltageScale::Scale2) => 150_000_000,
        (Pllvcosel::WideVco, VoltageScale::Scale3) => 100_000_000,
        (Pllvcosel::MediumVco, VoltageScale::Scale0 | VoltageScale::Scale1) => 210_000_000,
        (Pllvcosel::MediumVco, VoltageScale::Scale2) => 160_000_000,
        (Pllvcosel::MediumVco, VoltageScale::Scale3) => 88_000_000,
    };
    for output in outputs.iter().flatten() {
        assert!(output.0 <= maximum, "pll output exceeds voltage/mode limit");
    }
}

